CREATE TABLE credentials(id BIGSERIAL PRIMARY KEY,name VARCHAR(150) NOT NULL,username VARCHAR(150) NOT NULL,encrypted_password TEXT NOT NULL,encryption_iv VARCHAR(255) NOT NULL,auth_type VARCHAR(30) NOT NULL DEFAULT 'PASSWORD',created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());-- V1 already declares these machine columns; IF NOT EXISTS keeps this migration applicable on a fresh database.
ALTER TABLE machines ADD COLUMN IF NOT EXISTS preferred_credential_id BIGINT;ALTER TABLE machines ADD CONSTRAINT fk_machines_preferred_credential FOREIGN KEY(preferred_credential_id) REFERENCES credentials(id);ALTER TABLE machines ADD COLUMN IF NOT EXISTS ssh_host_key TEXT;ALTER TABLE machines ADD COLUMN IF NOT EXISTS ssh_fingerprint TEXT;ALTER TABLE machines ADD COLUMN IF NOT EXISTS fingerprint_verified_at TIMESTAMPTZ;
